static std::string statsBytes(const SourcePhysicsPointTraceStatisticsCandidate&s){std::ostringstream out(std::ios::binary);supportPut(out,s.outcomes);supportPut(out,s.packedSearches);supportPut(out,s.walkSearches);for(auto x:s.leafOrdinals)supportPut(out,x);return out.str();}
int main(int argc,char**argv){try{
    if(argc!=2)throw std::runtime_error("owned safety PHY required");std::ifstream in(argv[1],std::ios::binary);if(!in)throw std::runtime_error("safety PHY read");const std::vector<uint8_t>b((std::istreambuf_iterator<char>(in)),{});const auto before=b;const SourcePhyPointTraceCandidate shape(b);unsigned checks=0;auto require=[&](bool ok,const char*name){if(!ok)throw std::runtime_error(name);++checks;};SourcePhysicsSupportCacheCandidate cache;cache.generation=65535;cache.entries.fill(65535);SourcePhysicsPointTraceStatisticsCandidate stats;
    for(unsigned j=0;j<32;++j){const std::array<float,3>start{float(j)-16,j%2?-0.f:0.f,float(j)*.25f},delta{float(j)*.125f,-float(j),j%2?0.f:-0.f},origin{5,6,7},angles{15,37,-11};const auto got=shape.tracePoint(start,delta,origin,angles,0,&cache,&stats);SourcePhysicsSearchTraceCandidate expected;for(unsigned k=0;k<3;++k){expected.start[k]=start[k]+0.f;expected.end[k]=delta[k]+expected.start[k];}require(traceBytes(got)==traceBytes(expected),"mask0 analytic result");require(stats.outcomes[1]==0&&stats.outcomes[2]==0&&stats.outcomes[3]==0&&stats.outcomes[4]==0&&stats.packedSearches==0&&stats.walkSearches==0,"mask0 no search");require(cache.generation==65535&&cache.entries[0]==65535,"filtered persistent cache unchanged");}
    for(unsigned j=0;j<16;++j){std::array<float,3>start{},delta{},origin{},angles{};const float bad=std::numeric_limits<float>::infinity();if(j<3)start[j]=bad;else if(j<6)delta[j-3]=bad;else if(j<9)origin[j-6]=bad;else if(j<12)angles[j-9]=bad;else if(j==12)angles[0]=36001;else if(j==13){start[0]=std::numeric_limits<float>::max();origin[0]=-start[0];}else if(j==14){delta.fill(std::numeric_limits<float>::max());}else start[0]=std::numeric_limits<float>::max();stats.outcomes.fill(99);stats.leafOrdinals={42};stats.walkSearches=77;const auto oldStats=statsBytes(stats);const auto oldCache=cache;bool failed=false;try{shape.tracePoint(start,delta,origin,angles,1,&cache,&stats);}catch(const std::exception&){failed=true;}require(failed,"invalid/overflow point query rejected");require(statsBytes(stats)==oldStats&&cache.entries==oldCache.entries&&cache.generation==oldCache.generation,"whole trace failure preserves outputs");}
    // Independent callers may share this immutable shape with separate scratch.
    std::array<std::string,4>parallel{};std::array<std::thread,4>threads;for(size_t i=0;i<threads.size();++i)threads[i]=std::thread([&,i](){try{parallel[i]=traceBytes(shape.tracePoint({0,0,0},{1,2,3},{0,0,0},{0,0,0},1));}catch(const std::exception&e){parallel[i]=std::string("ERROR ")+e.what();}});for(auto&t:threads)t.join();const auto serial=traceBytes(shape.tracePoint({0,0,0},{1,2,3},{0,0,0},{0,0,0},1));for(const auto&s:parallel)require(s==serial,"parallel immutable trace agrees");require(b==before,"source input bytes unchanged");
    std::cout<<"PASS whole point-trace analytical/transaction/concurrency checks="<<checks<<'\n';return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
